source('highres_VisiumHD/analysis/hd_mp10_treg_endo_precommunication_v1/code/common.R');library(AUCell);top<-readLines(file.path(P,'neighborhood_mp10_calibration_v5/01_score_fidelity/top20.txt'));rr<-list()
for(unit in c('cell','bin8','bin16')){x<-as(readMM(file.path(root,'temporary',paste0(unit,'_AUCell.mtx'))),'dgCMatrix');rownames(x)<-readLines(file.path(root,'temporary',paste0(unit,'_genes.txt')));colnames(x)<-rd(paste0(unit,'_AUCell_ids.tsv'))$id
for(seed in c(123,124,125)){set.seed(seed);r<-AUCell_buildRankings(as.matrix(x),plotStats=FALSE,verbose=FALSE,keepZeroesAsNA=TRUE);a<-AUCell_calcAUC(list(MP10=top),r,aucMaxRank=ceiling(nrow(x)*.05),verbose=FALSE);# exact formula check against the same realized ranks
rank<-getRanking(r)[top,];K<-ceiling(nrow(x)*.05);expected<-colSums(pmax(K-rank,0),na.rm=TRUE)/sum(K-seq_along(top));stopifnot(max(abs(expected-as.numeric(getAUC(a))))<1e-12);rr[[paste(unit,seed)]]<-data.frame(unit=unit,id=colnames(x),seed=seed,official_auc=as.numeric(getAUC(a)),same_rank_formula=expected,formula_equal=TRUE)}
};put(do.call(rbind,rr),'official_AUCell_validation.tsv');writeLines(as.character(packageVersion('AUCell')),file.path(root,'logs/AUCell_version.txt'))
